"""Pliage : plieuses de l'atelier et leur outillage (fiche Bystronic Xpert PRO 200, mêmes outils sur les deux machines)."""

PLIEUSES = [("Plieuse 2 m / 50 t", 2000, 50), ("Plieuse 3 m / 200 t", 3000, 200)]
# (ouverture, angle, rayon d'épaule, force max à l'angle du vé, force max à 90°, vendu en ligne)
VES = [(8, 30, 1, 300, 1000, True), (12, 30, 1.5, 250, 900, True), (16, 30, 2, 250, 1000, True), (24, 30, 3, 300, 1100, True),
       (32, 30, 4, 300, 1100, True), (50, 60, 5, 1000, 1800, True), (80, 80, 10, 1400, 1600, False)]
# (nom, angle de nez, rayon, hauteur, force max)
POINCONS = [("P4 RF-A H175", 85, 1.5, 175, 900), ("P5 RF-A H175", 30, 1, 175, 1000), ("P7 RF-A H250", 30, 3, 250, 1400)]


def creer(apps, schema_editor):
    Plieuse = apps.get_model("decoupe", "Plieuse")
    Ve = apps.get_model("decoupe", "Ve")
    Poincon = apps.get_model("decoupe", "Poincon")
    apps.get_model("decoupe", "ReglagePliage").objects.get_or_create(pk=1)
    for nom, longueur, force in PLIEUSES:
        plieuse, cree = Plieuse.objects.get_or_create(nom=nom, defaults={"longueur_max_mm": longueur, "force_max_t": force})
        if not cree:
            continue
        for ouverture, angle, rayon, f_angle, f_90, en_ligne in VES:
            Ve.objects.create(plieuse=plieuse, ouverture_mm=ouverture, angle_deg=angle, rayon_epaule_mm=rayon,
                              force_max_angle_kn_m=f_angle, force_max_90_kn_m=f_90, vendable_en_ligne=en_ligne)
        for nom_p, angle, rayon, hauteur, f_max in POINCONS:
            Poincon.objects.create(plieuse=plieuse, nom=nom_p, angle_nez_deg=angle, rayon_mm=rayon, hauteur_mm=hauteur, force_max_kn_m=f_max)


